// CSD_RATIONALE_BEGIN
// Root-cause diagnosis for attempt 33's failures:
//
// (1) repetition_loop (10 examples): Phase 1 stopped at the FIRST "<<" token
//     emitted mid-reasoning (e.g., "the total is <<n * m"). Phase 2 then called
//     CloseSpanWithinBudget with currentConstrained=[], which generated fresh content
//     APPENDED after the partial "n * m" already in generated (e.g., "<<n * m - 0 - 0...").
//     The parser accepted "expr - 0" as complete, producing garbage.
//
// (2) semantic_mismatch (29 examples): Intercepting at the first "<<" truncated the
//     model's reasoning chain. Phase 2 generated a semantically wrong expression from
//     the truncated context instead of letting the model complete its natural derivation.
//
// Fix: Run Phase 1 as FULL unconstrained generation (849 steps) without ANY "<<"
// detection. The model naturally writes "<<int(expr)>>" at the end of step-by-step
// reasoning. The evaluator takes the LAST visible span (confirmed: last_visible_span
// 49/49), so mid-reasoning spans are superseded by the correct final one.
// Phase 3 (51 steps: 1 open + 50 close) forces a fresh constrained span ONLY if
// the model produced no complete "<<...>>" at all.
//
// This eliminates Phase 2's harmful intervention on mid-reasoning spans while
// preserving the constrained-decoding fallback for cases where the model never
// emits a complete span.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   if-branch (insideConstrained == true on entry):
//     CloseSpanWithinBudget postcondition directly guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut); implication is preserved
//     whether the span closes (antecedent false) or remains open (consequent
//     directly provided). ✓
//
//   else-branch Phase 1 loop:
//     Loop invariant !insideConstrainedOut makes the implication vacuously true
//     on every iteration. UnconstrainedStep does not modify insideConstrainedOut
//     or currentConstrainedOut, so the invariant is trivially preserved. ✓
//
//   else-branch Phase 3 (closeCount == 0):
//     OpenConstrainedSpan sets insideConstrainedOut := true, currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by the method's requires clause. ✓
//     CloseSpanWithinBudget postcondition then guarantees insideOut ==>
//     parser.IsValidPrefix(currentOut) for the returned state. ✓
//
//   else-branch Phase 3 skipped (closeCount >= 1 or budget exhausted):
//     insideConstrainedOut stayed false throughout; implication is vacuously true. ✓
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
//   Initialization: |generated| = |generatedPrefix|, steps = 0. ✓
//
//   if-branch: CloseSpanWithinBudget gives |generatedOut| <= |generated| + budget0;
//     steps grows by budget0. |generated_new| <= |generatedPrefix| + steps_new. ✓
//
//   else-branch Phase 1 non-EOS branch: appends 1 token, steps += 1; Δ balanced. ✓
//   else-branch Phase 1 EOS branch: steps += 1, generated unchanged; strictly
//     below bound after increment. ✓
//
//   Phase 3 OpenConstrainedSpan: appends "<<" (1 token), steps += 1.
//     |generated_new| = |generated_old| + 1 = |generatedPrefix| + steps_new. ✓
//   Phase 3 CloseSpanWithinBudget: |generatedOut| <= |generated| + budget3,
//     steps_new = steps_old + budget3.
//     EOS tokens and rejected suffix tokens inside CloseSpanWithinBudget consume
//     step budget without growing visible output, so visible growth <= budget3. ✓
//
//   Budget accounting: phase1Budget (≤ maxSteps − 51) + 1 (open) + 50 (close)
//     = maxSteps when maxSteps > 51. ✓
//
// Progress guarantee (cost > 0 when maxSteps > 0):
//   if-branch: budget0 >= 1 (remaining0 = maxSteps >= 1), cost = budget0 > 0. ✓
//   else-branch: phase1Budget >= 1 (since maxSteps >= 1), loop executes at least
//     one UnconstrainedStep, steps >= 1, cost >= 1 > 0. ✓
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. " +
    "When you have the final answer, write it as: <<int(expr)>> " +
    "where expr uses variable names from the problem and operators +, -, *, /, //, (, ), int(). " +
    "Example: <<int(n * price - discount)>>");

  var spanBudget: nat := 50;
  var steps: nat := 0;

  if insideConstrainedOut {
    // Entry with an already-open constrained span: close it immediately.
    if steps < maxSteps {
      var remaining0: nat := maxSteps - steps;
      var budget0: nat;
      if remaining0 < spanBudget {
        budget0 := remaining0;
      } else {
        budget0 := spanBudget;
      }
      var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget0
      );
      generated := cg0;
      insideConstrainedOut := ci0;
      currentConstrainedOut := cc0;
      steps := steps + budget0;
    }
  } else {
    // Phase 1: Full unconstrained generation — do NOT stop at "<<".
    // Let the model reason completely and emit <<int(expr)>> naturally at the end.
    var phase1Budget: nat;
    if maxSteps > spanBudget + 1 {
      phase1Budget := maxSteps - spanBudget - 1;
    } else {
      phase1Budget := maxSteps;
    }

    while steps < phase1Budget
      invariant 0 <= steps <= phase1Budget
      invariant phase1Budget <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases phase1Budget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Phase 3: If no complete << >> pair exists in output, force one.
    // The evaluator uses the LAST visible span, so a forced final span is safe.
    var generatedStr := CSDHelpers.PrefixToString(generated);
    var closeCount := CSDHelpers.CountSubstring(generatedStr, ">>");

    if closeCount == 0 && steps < maxSteps {
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;

      if insideConstrainedOut && steps < maxSteps {
        var remaining3: nat := maxSteps - steps;
        var budget3: nat;
        if remaining3 < spanBudget {
          budget3 := remaining3;
        } else {
          budget3 := spanBudget;
        }
        var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget3
        );
        generated := cg3;
        insideConstrainedOut := ci3;
        currentConstrainedOut := cc3;
        steps := steps + budget3;
      }
    }
  }

  cost := steps;

